<?php
namespace App\Http\Controllers;use App\Models\{AccessPoint,Floor};use App\Services\CongestionAnalysisService;use Carbon\Carbon;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\View\View;
class AccessPointController extends Controller{
 public function index(Request $r,CongestionAnalysisService $service):View{abort_unless($r->user()->can('dashboard.view'),403);$from=now()->subDay();$to=now();$aps=AccessPoint::with(['floor.building','radios','latestLoadSample'])->orderBy('name')->get()->map(function($ap)use($service,$from,$to){$ap->analysis=$service->analyse($ap,$from,$to);return$ap;});$floors=Floor::with('building')->orderBy('name')->get();return view('access-points.index',compact('aps','from','to','floors'));}
 public function store(Request $r):JsonResponse{abort_unless($r->user()->can('locations.manage'),403);$d=$r->validate(['floor_id'=>'required|exists:floors,id','survey_area_id'=>'nullable|exists:survey_areas,id','name'=>'required|string|max:150','identifier'=>'required|string|max:120|unique:access_points,identifier','vendor'=>'nullable|string|max:100','model'=>'nullable|string|max:100','management_ip'=>'nullable|ip','x_normalized'=>'nullable|numeric|between:0,1','y_normalized'=>'nullable|numeric|between:0,1','configured_client_limit'=>'nullable|integer|between:1,5000']);return response()->json(AccessPoint::create($d),201);}
 public function sample(Request $r,AccessPoint $accessPoint):JsonResponse{abort_unless($r->user()->can('measurements.import'),403);$d=$r->validate(['access_point_radio_id'=>'nullable|exists:access_point_radios,id','connected_clients'=>'nullable|integer|min:0|max:100000','channel_utilisation_percent'=>'nullable|numeric|between:0,100','throughput_mbps'=>'nullable|numeric|min:0','latency_ms'=>'nullable|numeric|min:0','packet_loss_percent'=>'nullable|numeric|between:0,100','rx_bytes'=>'nullable|integer|min:0','tx_bytes'=>'nullable|integer|min:0','noise_floor_dbm'=>'nullable|integer|between:-150,0','cpu_percent'=>'nullable|numeric|between:0,100','memory_percent'=>'nullable|numeric|between:0,100','source_type'=>'required|in:controller,snmp,csv,manual','sampled_at'=>'required|date','raw_payload'=>'nullable|array']);return response()->json($accessPoint->loadSamples()->create($d),201);}
 public function analysis(Request $r,AccessPoint $accessPoint,CongestionAnalysisService $service):JsonResponse{abort_unless($r->user()->can('dashboard.view'),403);$d=$r->validate(['from'=>'nullable|date','to'=>'nullable|date|after_or_equal:from']);$to=isset($d['to'])?Carbon::parse($d['to']):now();$from=isset($d['from'])?Carbon::parse($d['from']):$to->copy()->subDay();return response()->json($service->analyse($accessPoint,$from,$to));}}
